import Foundation

/// The G3PLX QPSK31 rate-1/2, K = 5 convolutional code.
///
/// Source: P. Martinez G3PLX, "PSK31: A New Radio-Teletype Mode", QEX July/Aug 1999, sidebar
/// "The Convolutional Code". Each run of five Varicode bits (oldest on the left) selects the phase
/// shift applied to the carrier: 0 = none, 1 = advance 90°, 2 = reversal, 3 = retard 90°. An advancing
/// phase is higher in RF, so on USB audio a shift of 1 is +90° on the audio carrier.
///
/// The table is generated by the generator polynomials 0x19 and 0x17 applied to the 5-bit window
/// (newest bit in bit 0): with parities a = ⊕(w & 0x19) and b = ⊕(w & 0x17), the shift is
/// [2, 3, 0, 1][2a + b]. `PSK31Tests.convolutionalCodeMatchesG3PLXTable` checks this against all
/// 32 entries of the published table and its worked example.
enum QPSKCode {
    static let constraintLength = 5
    static let polynomials: (UInt8, UInt8) = (0x19, 0x17)
    private static let shiftForParities: [Int] = [2, 3, 0, 1]

    /// Phase shift in quarter turns for a 5-bit window whose newest bit is bit 0.
    static func phaseShift(window w: Int) -> Int {
        let a = (w & Int(polynomials.0)).nonzeroBitCount & 1
        let b = (w & Int(polynomials.1)).nonzeroBitCount & 1
        return shiftForParities[2 * a + b]
    }

    /// `phaseShift` for all 32 windows.
    static let shifts: [Int] = (0..<32).map(phaseShift(window:))
}

/// Soft-decision Viterbi decoder for the QPSK31 code: 16 states (the last four bits), register-exchange
/// survivors, and a decision delay of 20 bits — four times the five-bit spread, as G3PLX specifies
/// (QEX 1999: "a decoder delay of four times the time spread, or 20 bits").
struct QPSKViterbi {
    static let delay = 4 * QPSKCode.constraintLength
    private static let states = 16

    private var metric = [Float](repeating: 0, count: states)
    private var next = [Float](repeating: 0, count: states)
    private var survivor = [UInt32](repeating: 0, count: states)
    private var nextSurvivor = [UInt32](repeating: 0, count: states)
    private var pushed = 0

    /// Feeds one differential symbol: the received phase shift as a vector (any scale), for example
    /// y[k]·conj(y[k-1]). Returns the bit decided `delay` symbols ago, once the delay has filled.
    mutating func push(_ d: SIMD2<Float>) -> Bool? {
        // Correlation of the received shift with each of the four ideal shifts 0, +90°, 180°, -90°.
        let score: (Float, Float, Float, Float) = (d.x, d.y, -d.x, -d.y)
        func branch(_ shift: Int) -> Float {
            switch shift {
            case 0: score.0
            case 1: score.1
            case 2: score.2
            default: score.3
            }
        }
        for s in 0..<Self.states {
            // Two predecessors p = (s >> 1) | (high << 3) reach state s with input bit s & 1.
            let bit = UInt32(s & 1)
            let p0 = s >> 1, p1 = (s >> 1) | 8
            let m0 = metric[p0] + branch(QPSKCode.shifts[(p0 << 1) | (s & 1)])
            let m1 = metric[p1] + branch(QPSKCode.shifts[(p1 << 1) | (s & 1)])
            if m0 >= m1 {
                next[s] = m0
                nextSurvivor[s] = survivor[p0] << 1 | bit
            } else {
                next[s] = m1
                nextSurvivor[s] = survivor[p1] << 1 | bit
            }
        }
        var best = 0
        for s in 1..<Self.states where next[s] > next[best] { best = s }
        let top = next[best]
        for s in 0..<Self.states { metric[s] = next[s] - top }
        swap(&survivor, &nextSurvivor)
        pushed += 1
        guard pushed > Self.delay else { return nil }
        return (survivor[best] >> UInt32(Self.delay)) & 1 == 1
    }

    mutating func reset() {
        for s in 0..<Self.states { metric[s] = 0; survivor[s] = 0 }
        pushed = 0
    }
}
